28	@PreAuthorize("hasRole('ADMIN')")
29	public class AdminContentController {
30	
31	    private static final Logger logger = LoggerFactory.getLogger(AdminContentController.class);
32	
33	    private final PostRepository postRepository;
34	    private final CommentRepository commentRepository;
35	    private final PostService postService;
36	
37	    public AdminContentController(PostRepository postRepository,
38	                                  CommentRepository commentRepository,
39	                                  PostService postService) {
40	        this.postRepository = postRepository;
41	        this.commentRepository = commentRepository;
42	        this.postService = postService;
43	    }
44	
45	    /**
46	     * 查看所有帖子（按状态筛选）
47	     * GET /api/admin/posts?status=PUBLISHED&page=0&size=20
48	     */
49	    @GetMapping("/posts")
50	    public ResponseEntity<Page<PostResponse>> getPostsByStatus(
51	            @RequestParam(required = false) String status,
52	            @RequestParam(defaultValue = "0") int page,
53	            @RequestParam(defaultValue = "20") int size
54	    ) {
55	        Page<PostResponse> response = postService.getPostList(page, size, status);
56	        return ResponseEntity.ok(response);
57	    }
58	
59	    /**
60	     * 修改帖子状态
61	     * PUT /api/admin/posts/{id}/status
62	     */
63	    @PutMapping("/posts/{id}/status")
64	    public ResponseEntity<ApiResponse<Void>> updatePostStatus(
65	            @PathVariable Long id,
66	            @RequestBody UpdatePostStatusRequest request
67	    ) {
68	        Post post = postRepository.findById(id)
69	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
70	
71	        post.setStatus(request.getStatus());
72	        postRepository.save(post);
73	
74	        logger.info("管理员修改帖子状态: id={}, status={}", id, request.getStatus());
75	
76	        return ResponseEntity.ok(ApiResponse.success("帖子状态已更新"));
77	    }
78	
79	    /**
80	     * 强制删除帖子
81	     * DELETE /api/admin/posts/{id}
82	     */
83	    @DeleteMapping("/posts/{id}")
84	    public ResponseEntity<ApiResponse<Void>> forceDeletePost(@PathVariable Long id) {
85	        Post post = postRepository.findById(id)
86	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
87	
88	        postRepository.delete(post);
89	
90	        logger.info("管理员强制删除帖子: id={}", id);
91	
92	        return ResponseEntity.ok(ApiResponse.success("帖子已删除"));
93	    }
94	
95	    /**
96	     * 查看所有评论（按时间倒序）
97	     * GET /api/admin/comments
98	     */
