                path="dashboard/comments"
                element={
                  <ProtectedRoute>
                    <MyCommentsPage />
                  </ProtectedRoute>
                }
              />

              <Route
                path="dashboard/drafts"
                element={
                  <ProtectedRoute>
                    <MyDraftsPage />
                  </ProtectedRoute>
                }
              />

              <Route
                path="dashboard/password"
                element={
                  <ProtectedRoute>
                    <ChangePasswordPage />
                  </ProtectedRoute>
                }
              />

              {/* 版块相关路由 */}
              <Route path="category/:id" element={<CategoryPage />} />

              {/* 帖子相关路由 */}
              <Route path="posts" element={<PostListPage />} />
              <Route path="posts/:id" element={<PostDetailPage />} />
              <Route
                path="posts/new"
                element={
                  <ProtectedRoute>
                    <CreatePostPage />
                  </ProtectedRoute>
                }
              />
              <Route
                path="posts/:id/edit"
                element={
                  <ProtectedRoute>
                    <EditPostPage />
                  </ProtectedRoute>
                }
              />

              {/* 搜索和通知路由 */}
              <Route path="search" element={<SearchPage />} />
              <Route
                path="notifications"
                element={
                  <ProtectedRoute>
                    <NotificationsPage />
                  </ProtectedRoute>
                }
              />

              {/* 404 */}
              <Route path="*" element={<NotFoundPage />} />
            </Route>

            {/* 管理后台路由 */}
            <Route path="/admin" element={
              <ProtectedRoute>
                <AdminRoutes />
              </ProtectedRoute>
            }>
              <Route index element={<AdminDashboard />} />
              <Route path="categories" element={<CategoryManage />} />
              <Route path="content" element={<ContentModeration />} />
              <Route path="users" element={<UserManage />} />

              {/* 404 */}
              <Route path="*" element={<NotFoundPage />} />
            </Route>
          </Routes>
          </ErrorBoundary>
        </AuthProvider>
      </BrowserRouter>
    </QueryClientProvider>
  );
}

export default App;

