1	import { useState } from 'react';
2	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
3	import {
4	  getCategories, createCategory, updateCategory, deleteCategory,
5	  type Category, type CreateCategoryRequest, type UpdateCategoryRequest
6	} from '../../api/category';
7	import ErrorMessage from '../../components/ErrorMessage';
8	import { queryKeys } from '../../lib/queryKeys';
9	
10	/**
11	 * 版块管理页面
12	 */
13	export default function CategoryManage() {
14	  const queryClient = useQueryClient();
15	
16	  const [showForm, setShowForm] = useState(false);
17	  const [editingId, setEditingId] = useState<number | null>(null);
18	  const [formData, setFormData] = useState<CreateCategoryRequest>({
19	    name: '',
20	    description: '',
21	    sortOrder: 0
22	  });
23	  const [error, setError] = useState('');
24	  const [success, setSuccess] = useState('');
25	
26	  // 使用 React Query 获取版块列表
27	  const { data: categories = [], isLoading } = useQuery({
28	    queryKey: queryKeys.categories.list(),
29	    queryFn: getCategories,
30	  });
31	
32	  const handleCreate = () => {
33	    setEditingId(null);
34	    setFormData({ name: '', description: '', sortOrder: categories.length });
35	    setShowForm(true);
36	    setError('');
37	    setSuccess('');
38	  };
39	
40	  const handleEdit = (category: Category) => {
41	    setEditingId(category.id);
42	    setFormData({
43	      name: category.name,
44	      description: category.description || '',
45	      sortOrder: category.sortOrder
46	    });
47	    setShowForm(true);
48	    setError('');
49	    setSuccess('');
50	  };
51	
52	  // 创建/更新版块的 mutation
53	  const saveMutation = useMutation({
54	    mutationFn: ({ id, data }: { id?: number; data: CreateCategoryRequest | UpdateCategoryRequest }) => {
55	      if (id) {
56	        return updateCategory(id, data as UpdateCategoryRequest);
57	      } else {
58	        return createCategory(data);
59	        return adminCreateCategory(data as CreateCategoryRequest);
60	      }
61	    },
62	    onSuccess: () => {
63	      queryClient.invalidateQueries({ queryKey: queryKeys.categories.list() });
64	      setShowForm(false);
65	      setSuccess(editingId ? '版块更新成功' : '版块创建成功');
66	      setEditingId(null);
67	    },
68	    onError: (err: any) => {
69	      setError(err.response?.data?.message || '操作失败');
70	    },
71	  });
72	
73	  // 删除版块的 mutation
74	  const deleteMutation = useMutation({
75	    mutationFn: deleteCategory,
76	    onSuccess: () => {
77	      queryClient.invalidateQueries({ queryKey: queryKeys.categories.list() });
78	      setSuccess('版块删除成功');
79	    },
80	    onError: (err: any) => {
81	      setError(err.response?.data?.message || '删除失败');
82	    },
83	  });
84	
85	  const handleDelete = async (id: number, name: string) => {
86	    if (!confirm(`确定要删除版块「${name}」吗？`)) return;
87	    deleteMutation.mutate(id);
88	  };
89	
90	  const handleSubmit = async (e: React.FormEvent) => {
91	    e.preventDefault();
92	    setError('');
93	
94	    if (!formData.name.trim()) {
95	      setError('版块名称不能为空');
96	      return;
97	    }
98	
99	    saveMutation.mutate({ id: editingId || undefined, data: formData });
100	  };
101	
102	  if (isLoading) {
103	    return (
104	      <div className="loading-container">
105	        <div className="spinner spinner-lg"></div>
106	        <span>加载中...</span>
107	      </div>
108	    );
109	  }
110	
