+        <div className="admin-sidebar-header">
+          <h2 style={{ margin: 0, fontSize: '1.2rem' }}>管理后台</h2>
+        </div>
+
+        <nav aria-label="管理导航">
+          {navItems.map((item) => (
+            <Link
+              key={item.to}
