91	 * Get or initialize database state from localStorage
92	 */
93	function getDbState(): MockDbState {
94	  const data = localStorage.getItem(STORAGE_KEY);
95	  if (!data) {
96	    localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_STATE));
97	    return INITIAL_STATE;
98	  }
99	  try {
100	    return JSON.parse(data);
101	  } catch (e) {
102	    localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_STATE));
103	    return INITIAL_STATE;
104	  }
105	}
