114	/**
115	 * Helper to build nested comment tree from flat list
116	 */
117	function buildCommentTree(flatComments: Comment[], postId: number): Comment[] {
118	  const postComments = flatComments.filter(c => c.postId === postId && c.status === 'APPROVED');
119	  const commentMap = new Map<number, Comment>();
120	
121	  postComments.forEach(c => {
122	    commentMap.set(c.id, { ...c, replies: [] });
123	  });
124	
125	  const roots: Comment[] = [];
126	
127	  commentMap.forEach(c => {
128	    if (c.parentId === null) {
129	      roots.push(c);
130	    } else {
131	      const parent = commentMap.get(c.parentId);
132	      if (parent) {
133	        parent.replies.push(c);
134	      } else {
135	        roots.push(c); // Fallback
136	      }
137	    }
138	  });
139	
140	  return roots;
141	}
