143	/**
144	 * Identify user from request Authorization header
145	 */
146	function getCurrentUser(config: AxiosRequestConfig): { username: string; role: string; id: number } | null {
147	  const authHeader = config.headers?.Authorization || config.headers?.authorization;
148	  let token = '';
149	
150	  if (typeof authHeader === 'string' && authHeader.startsWith('Bearer ')) {
151	    token = authHeader.replace('Bearer ', '');
152	  } else {
153	    // Fallback: check localStorage directly
154	    token = localStorage.getItem('access_token') || '';
155	  }
156	
157	  if (token && token.startsWith('mock-token-')) {
158	    const username = token.replace('mock-token-', '');
159	    const state = getDbState();
160	    const dbUser = state.users.find(u => u.username === username);
161	    if (dbUser) {
162	      return {
163	        username: dbUser.username,
164	        role: dbUser.role,
165	        id: dbUser.id
166	      };
167	    }
168	  }
169	  return null;
170	}
