172	/**
173	 * Mock Request Interceptor Adapter
174	 */
175	export async function mockRequestAdapter(config: AxiosRequestConfig): Promise<AxiosResponse<any>> {
176	  const state = getDbState();
177	  const url = config.url || '';
178	  const method = (config.method || 'GET').toUpperCase();
179	  const params = config.params || {};
180	  const data = config.data ? (typeof config.data === 'string' ? JSON.parse(config.data) : config.data) : {};
181	  const currentUser = getCurrentUser(config);
182	
183	  let responseData: any = null;
184	  let status = 200;
185	
186	  // Helper to paginate an array
187	  const paginateArray = <T>(arr: T[], page: number, size: number): PageResponse<T> => {
188	    const start = page * size;
189	    const end = start + size;
190	    const content = arr.slice(start, end);
191	    const totalElements = arr.length;
192	    const totalPages = Math.ceil(totalElements / size);
193	
194	    return {
195	      content,
196	      pageable: { pageNumber: page, pageSize: size },
197	      totalElements,
198	      totalPages,
199	      last: page >= totalPages - 1,
200	      first: page === 0,
201	      empty: content.length === 0
202	    };
203	  };
204	
205	  try {
206	    // ============ Auth API ============
207	    if (url.match(/^\/auth\/login/)) {
208	      const { username, password } = data;
209	      const userObj = state.users.find(u => u.username === username);
210	      // Mock validation: password is username + '123'
211	      if (userObj && password === `${username}123`) {
212	        if (userObj.isLocked) {
213	          status = 403;
214	          throw new Error('该账户已被锁定，请联系管理员！');
215	        }
216	        responseData = {
217	          accessToken: `mock-token-${username}`,
218	          refreshToken: `mock-refresh-${username}`,
219	          tokenType: 'Bearer',
220	          expiresIn: 3600
221	        };
222	      } else {
223	        status = 401;
224	        throw new Error('用户名或密码错误！');
225	      }
226	    } 
227	    else if (url.match(/^\/auth\/register/)) {
228	      const { username, email } = data;
229	      if (state.users.some(u => u.username === username)) {
230	        status = 400;
231	        throw new Error('用户名已存在！');
232	      }
233	      state.lastIds.user++;
234	      const newUserId = state.lastIds.user;
235	      
236	      const newAdminUser: AdminUser = {
237	        id: newUserId,
238	        username,
239	        email,
240	        role: 'USER',
241	        isLocked: false,
242	        createdAt: getNowString()
243	      };
244	
245	      const newProfile: UserProfile = {
246	        username,
247	        email,
248	        avatarUrl: null,
249	        bio: null,
250	        location: null,
251	        website: null,
252	        createdAt: getNowString()
253	      };
254	
255	      state.users.push(newAdminUser);
256	      state.profiles[username] = newProfile;
257	      saveDbState(state);
258	
259	      responseData = { username, email };
260	    }
261	    else if (url.match(/^\/auth\/resend-verification/)) {
262	      responseData = { message: 'Verification code sent', data: null };
263	    }
264	    else if (url.match(/^\/auth\/forgot-password/)) {
265	      responseData = { message: '验证码已发送至您的邮箱！' };
266	    }
267	    else if (url.match(/^\/auth\/reset-password/)) {
268	      responseData = { message: '密码重置成功，请重新登录！' };
269	    }
270	    else if (url.match(/^\/auth\/refresh/)) {
271	      const { refreshToken } = data;
272	      if (refreshToken && refreshToken.startsWith('mock-refresh-')) {
273	        const username = refreshToken.replace('mock-refresh-', '');
274	        responseData = {
275	          accessToken: `mock-token-${username}`,
276	          refreshToken: `mock-refresh-${username}`,
277	          tokenType: 'Bearer',
278	          expiresIn: 3600
279	        };
280	      } else {
281	        status = 401;
282	        throw new Error('Refresh token invalid');
283	      }
284	    }
285	    else if (url.match(/^\/auth\/logout/)) {
286	      responseData = null;
287	    }
288	
289	    // ============ Category API ============
290	    else if (url === '/categories' && method === 'GET') {
291	      responseData = state.categories;
292	    }
293	    else if (url.match(/^\/categories\/\d+$/) && method === 'GET') {
294	      const catId = parseInt(url.split('/').pop() || '0');
295	      const category = state.categories.find(c => c.id === catId);
296	      if (!category) {
297	        status = 404;
298	        throw new Error('该分类版块不存在！');
299	      }
300	      responseData = category;
301	    }
302	    // Admin category management routes
303	    else if ((url === '/categories' || url === '/admin/categories') && method === 'POST') {
304	      if (!currentUser || currentUser.role !== 'ADMIN') {
305	        status = 403;
306	        throw new Error('权限不足！');
307	      }
308	      state.lastIds.category++;
309	      const newCat: Category = {
310	        id: state.lastIds.category,
311	        name: data.name,
312	        description: data.description || '',
313	        sortOrder: data.sortOrder || 1,
314	        createdAt: getNowString()
