319	    }
320	    else if ((url.match(/^\/categories\/\d+$/) || url.match(/^\/admin\/categories\/\d+$/)) && method === 'PUT') {
321	      if (!currentUser || currentUser.role !== 'ADMIN') {
322	        status = 403;
323	        throw new Error('权限不足！');
324	      }
325	      const catId = parseInt(url.split('/').pop() || '0');
326	      const idx = state.categories.findIndex(c => c.id === catId);
327	      if (idx === -1) {
328	        status = 404;
329	        throw new Error('分类不存在！');
