339	    }
340	    else if ((url.match(/^\/categories\/\d+$/) || url.match(/^\/admin\/categories\/\d+$/)) && method === 'DELETE') {
341	      if (!currentUser || currentUser.role !== 'ADMIN') {
342	        status = 403;
343	        throw new Error('权限不足！');
344	      }
345	      const catId = parseInt(url.split('/').pop() || '0');
346	      state.categories = state.categories.filter(c => c.id !== catId);
347	      // Optionally cascade delete posts
348	      state.posts = state.posts.filter(p => p.categoryId !== catId);
349	      saveDbState(state);
350	      responseData = null;
351	    }
352	
353	    // ============ Post API ============
354	    else if (url === '/posts' && method === 'GET') {
355	      const page = parseInt(params.page || '0');
356	      const size = parseInt(params.size || '10');
357	      const statusParam = params.status;
358	
359	      let filtered = state.posts;
360	      if (statusParam) {
361	        filtered = filtered.filter(p => p.status === statusParam);
362	      } else {
363	        // Normal list shows APPROVED only
364	        filtered = filtered.filter(p => p.status === 'APPROVED');
365	      }
366	      
367	      // Sort: pinned first (our mock does not have pinned but we sort by id desc)
368	      filtered = [...filtered].sort((a, b) => b.id - a.id);
369	      responseData = paginateArray(filtered, page, size);
370	    }
371	    else if (url.match(/^\/posts\/by-category\/\d+$/) && method === 'GET') {
372	      const catId = parseInt(url.split('/').pop() || '0');
373	      const page = parseInt(params.page || '0');
374	      const size = parseInt(params.size || '10');
375	      const filtered = state.posts
376	        .filter(p => p.categoryId === catId && p.status === 'APPROVED')
377	        .sort((a, b) => b.id - a.id);
378	      
379	      responseData = paginateArray(filtered, page, size);
380	    }
381	    else if (url === '/posts/search' && method === 'GET') {
382	      const keyword = (params.keyword || '').toLowerCase();
383	      const page = parseInt(params.page || '0');
384	      const size = parseInt(params.size || '10');
385	      const filtered = state.posts
386	        .filter(p => p.status === 'APPROVED' && (p.title.toLowerCase().includes(keyword) || p.content.toLowerCase().includes(keyword)))
387	        .sort((a, b) => b.id - a.id);
388	      
389	      responseData = paginateArray(filtered, page, size);
390	    }
